'use strict';
/* CHỈ DÙNG KHI KIỂM THỬ – thay thế tối thiểu cho gói "pg" bằng chương trình psql của PostgreSQL thật (máy kiểm thử không cài được npm).
   Mục đích: chạy ĐÚNG các câu SQL của server.js (bảng, UNNEST, ON CONFLICT, JSONB) trên máy chủ PostgreSQL 16 thật.
   KHÔNG kiểm được: tầng giao thức/kết nối của gói pg thật (bể kết nối, SSL, mất kết nối giữa chừng) – phần đó chạy ở CI (xem .github/workflows).
   Tham số $1..$n được thay bằng hằng SQL đã thoát ký tự (standard_conforming_strings=on); kết quả SELECT lấy qua json_agg → giống pg (jsonb → đối tượng). */
const {execFile}=require('node:child_process');
const lit=v=>{if(v===null||v===undefined)return 'NULL';if(typeof v==='number'||typeof v==='bigint')return String(v);if(typeof v==='boolean')return v?'TRUE':'FALSE';
 if(Array.isArray(v))return v.length?'ARRAY['+v.map(lit).join(',')+']':"'{}'";if(typeof v==='object')v=JSON.stringify(v);return "'"+String(v).replace(/'/g,"''")+"'"};
function bind(text,params){return text.replace(/\$(\d+)/g,(_,i)=>{const k=+i-1;if(!params||k>=params.length)throw Error('thiếu tham số $'+i);return lit(params[k])})}
class Pool{constructor(o){this.url=o&&o.connectionString;this.n=0}
 query(text,params){const sql=bind(text,params);const isSel=/^\s*select\b/i.test(sql);
  const q=isSel?`SELECT coalesce(json_agg(t),'[]'::json) FROM (${sql}) t;`:sql+';';
  return new Promise((ok,bad)=>{const p=execFile('psql',['-X','-q','-A','-t','-v','ON_ERROR_STOP=1','-d',this.url],{maxBuffer:256*1024*1024},(e,out,err)=>{
    if(e)return bad(Object.assign(Error(String(err||e.message).trim()),{code:'PSQL'}));ok({rows:isSel?JSON.parse(out.trim()||'[]'):[],rowCount:0})});p.stdin.end(q)})}
 on(){return this} end(){return Promise.resolve()}}
module.exports={Pool,_bind:bind};
